CREATE OR REPLACE FUNCTION public.approve_income_expense_v1(p_voucher_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
declare
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_row public.income_expenses%rowtype;
  v_rows integer;
begin
  if v_actor is null then
    raise exception 'Chưa đăng nhập' using errcode = '42501';
  end if;

  select * into v_row from public.income_expenses
   where id = p_voucher_id and deleted_at is null
   for update;
  if not found then
    raise exception 'Không thể duyệt phiếu: phiếu không tồn tại hoặc bạn không có quyền duyệt phiếu này'
      using errcode = '42501';
  end if;

  -- Row legacy → tín hiệu fallback (hook chuyển sang approve_voucher legacy).
  if not app_private.is_income_expense_flow_owned(v_row.id) then
    raise exception 'Phiếu chưa thuộc luồng canonical — dùng đường legacy'
      using errcode = '55000';
  end if;

  if v_row.approval_status = 'APPROVED' then
    return; -- idempotent no-op
  end if;

  -- t5_26: phiếu đang chờ engine → chỉ quyết qua màn Chờ duyệt
  perform app_private.assert_no_engine_request_v1(v_row.id);

  if v_row.approval_status = 'CANCELLED' then
    -- Phương án A: phiếu huỷ là terminal — dùng nút "Tạo bản sao".
    raise exception 'Phiếu đã huỷ — không thể duyệt. Hãy dùng "Tạo bản sao" để lập phiếu mới.';
  end if;

  -- Parity legacy: phải có sổ quỹ trước khi duyệt.
  if v_row.account_id is null then
    raise exception 'Phiếu chưa có sổ quỹ — bấm Sửa phiếu, chọn sổ quỹ rồi mới duyệt được.';
  end if;

  -- Permission parity với public.approve_voucher.
  if not (
    v_row.user_id = v_actor
    or public.is_super_admin()
    or (v_row.building_id is not null
        and public.can_do_on_building('income_expenses', 'approve', v_row.building_id))
  ) then
    raise exception 'Không thể duyệt phiếu: phiếu không tồn tại hoặc bạn không có quyền duyệt phiếu này'
      using errcode = '42501';
  end if;

  v_actor_name := app_private.ie_actor_display_name_v1(v_actor);

  insert into app_private.ie_transition_authorization (income_expense_id, xid, purpose)
  values (v_row.id, pg_current_xact_id(), 'APPROVED');

  update public.income_expenses
     set approval_status = 'APPROVED',
         approved_by = v_actor,
         approved_at = now()
   where id = v_row.id;
  get diagnostics v_rows = row_count;

  delete from app_private.ie_transition_authorization
   where income_expense_id = v_row.id and xid = pg_current_xact_id();

  if v_rows <> 1 then
    raise exception 'approve transition affected % rows (expected 1)', v_rows
      using errcode = '55000';
  end if;

  perform app_private.append_income_expense_event_v1(
    v_row.organization_id, v_row.id, 'APPROVED', v_actor, v_actor_name,
    v_row.approval_status, 'APPROVED', 'Duyệt qua approve_income_expense_v1');
end;
$function$

CREATE OR REPLACE FUNCTION public.income_expenses_check_profit_lock()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public', 'app_private'
AS $function$
DECLARE
  v_mien text[];
  v_scope text;
BEGIN
  -- Đường nhanh: cả vị trí cũ lẫn mới đều ở tháng đang mở.
  IF NOT (
    (TG_OP <> 'INSERT' AND app_private.profit_month_locked_v1(OLD.building_id, OLD.voucher_date))
    OR (TG_OP <> 'DELETE' AND app_private.profit_month_locked_v1(NEW.building_id, NEW.voucher_date))
  ) THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'UPDATE' THEN
    -- Cột KHÔNG đổi tiền: máy dời lịch phiếu lặp, gắn/nhả phiên bàn giao tiền
    -- mặt, đánh dấu đã kiểm, cờ hạng mục hạn chế (suy từ loại thu chi).
    v_mien := ARRAY['repeat_remaining', 'repeat_next_date', 'handover_id',
                    'verified_at', 'verified_by', 'verified_by_name', 'verified_note',
                    'has_restricted_item', 'updated_at'];
    -- Ba cột vòng đời được điền khi còn NULL: chỉ miễn đúng chiều NULL -> giá trị.
    IF OLD.posting_mode IS NULL THEN v_mien := v_mien || 'posting_mode'::text; END IF;
    IF OLD.posting_status IS NULL THEN v_mien := v_mien || 'posting_status'::text; END IF;
    IF OLD.review_state IS NULL THEN v_mien := v_mien || 'review_state'::text; END IF;

    IF (to_jsonb(OLD) - v_mien) IS NOT DISTINCT FROM (to_jsonb(NEW) - v_mien) THEN
      RETURN NEW;
    END IF;

    SELECT w.scope INTO v_scope
      FROM app_private.ie_flex_writer_xids w
     WHERE w.income_expense_id = OLD.id
       AND w.transaction_id = pg_current_xact_id()
       AND w.backend_pid = pg_backend_pid();

    -- Dừng lặp lại: chỉ tắt việc sinh phiếu tương lai, không đụng số nào của kỳ.
    IF v_scope = 'STOP_RECURRING'
       AND COALESCE(NEW.repeat_cycle, 'NONE') = 'NONE'
       AND (to_jsonb(OLD) - v_mien - ARRAY['repeat_cycle', 'repeat_infinity', 'repeat_count'])
           IS NOT DISTINCT FROM
           (to_jsonb(NEW) - v_mien - ARRAY['repeat_cycle', 'repeat_infinity', 'repeat_count']) THEN
      RETURN NEW;
    END IF;

    -- Tạo hợp đồng gắn phiếu cọc giữ chỗ: chỉ contract_id đi từ NULL.
    IF v_scope = 'LINK_CONTRACT'
       AND OLD.contract_id IS NULL
       AND NEW.contract_id IS NOT NULL
       AND (to_jsonb(OLD) - v_mien - 'contract_id'::text)
           IS NOT DISTINCT FROM
           (to_jsonb(NEW) - v_mien - 'contract_id'::text) THEN
      RETURN NEW;
    END IF;
  END IF;

  IF TG_OP <> 'INSERT' THEN
    PERFORM app_private.assert_profit_month_open_v2(
      OLD.building_id, OLD.voucher_date,
      CASE WHEN TG_OP = 'DELETE' THEN 'xoá phiếu' ELSE 'sửa phiếu' END);
  END IF;
  IF TG_OP <> 'DELETE' THEN
    PERFORM app_private.assert_profit_month_open_v2(
      NEW.building_id, NEW.voucher_date,
      CASE WHEN TG_OP = 'INSERT' THEN 'lập phiếu' ELSE 'sửa phiếu' END);
  END IF;

  RETURN COALESCE(NEW, OLD);
END
$function$

CREATE OR REPLACE FUNCTION public.pay_draft_fee_voucher(p_voucher_id uuid, p_account_id uuid, p_attachments jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_st    text;
  v_del   timestamptz;
  v_bld   uuid;
  v_owner uuid;
  v_acc   uuid;
  v_code  text;
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Bạn chưa đăng nhập' USING ERRCODE = '42501';
  END IF;
  IF p_account_id IS NULL THEN
    RAISE EXCEPTION 'Chọn sổ quỹ ghi chi trước khi thanh toán';
  END IF;

  SELECT ie.approval_status, ie.deleted_at, ie.building_id INTO v_st, v_del, v_bld
    FROM income_expenses ie WHERE ie.id = p_voucher_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy phiếu' USING ERRCODE = 'P0002'; END IF;

  -- ── GATE QUYỀN TOÀ — TRƯỚC mọi tiết lộ trạng thái (P2-06, 31/08) ──
  -- Cùng vị ngữ với pay_period_fee. Không-quyền và không-tồn-tại trả CÙNG một
  -- câu: caller ngoài org không phân biệt được "không có phiếu" với "có mà
  -- không được xem" ⇒ hết đường dò.
  SELECT b.user_id INTO v_owner
    FROM buildings b WHERE b.id = v_bld AND b.deleted_at IS NULL;
  IF v_bld IS NULL OR v_owner IS NULL
     OR NOT (public.can_access_building(v_bld)
             OR public.ie_all_buildings_scope(v_bld)
             OR v_owner = auth.uid()
             OR public.is_admin() OR public.is_super_admin()) THEN
    RAISE EXCEPTION 'Không tìm thấy phiếu' USING ERRCODE = 'P0002';
  END IF;

  IF v_del IS NOT NULL THEN RAISE EXCEPTION 'Phiếu đã bị hủy'; END IF;
  IF v_st <> 'UNAPPROVED' THEN
    RAISE EXCEPTION 'Phiếu không ở trạng thái nháp (hiện: %)', v_st;
  END IF;

  SELECT id INTO v_acc FROM accounts
   WHERE id = p_account_id AND deleted_at IS NULL
     AND (user_id = auth.uid() OR public.is_admin() OR public.is_super_admin());
  IF v_acc IS NULL THEN
    RAISE EXCEPTION 'Sổ quỹ không hợp lệ hoặc bạn không có quyền ghi chi vào sổ này' USING ERRCODE = '42501';
  END IF;

  UPDATE income_expenses
     SET account_id  = v_acc,
         attachments = COALESCE(p_attachments, attachments)
   WHERE id = p_voucher_id;

  -- Duyệt qua approve_voucher: giữ nguyên gate quyền duyệt + audit; RAISE → rollback cả sổ/ảnh.
  PERFORM public.approve_voucher(p_voucher_id);

  SELECT code INTO v_code FROM income_expenses WHERE id = p_voucher_id;
  RETURN jsonb_build_object('ok', true, 'voucher_id', p_voucher_id, 'code', v_code);
END;
$function$

CREATE OR REPLACE FUNCTION public.set_user_id_from_auth()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.user_id IS NULL THEN
    NEW.user_id := auth.uid();
  END IF;
  RETURN NEW;
END;
$function$
